-- Disposable fixtures inside a transaction. No emails, real staff or payments.
begin;
create temp table work_test_ids(owner_id uuid, editor_id uuid, session_id uuid, editor_session uuid, factor_id uuid, editor_factor uuid);
insert into work_test_ids values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant select on work_test_ids to authenticated,anon;
insert into auth.users(id,email,email_confirmed_at) select owner_id,'owner-fixture@example.invalid',now() from work_test_ids union all select editor_id,'editor-fixture@example.invalid',now() from work_test_ids;
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) select factor_id,owner_id,'totp'::auth.factor_type,'verified'::auth.factor_status,'TEST-NOT-A-REAL-AUTHENTICATOR',now(),now() from work_test_ids union all select editor_factor,editor_id,'totp'::auth.factor_type,'verified'::auth.factor_status,'TEST-NOT-A-REAL-AUTHENTICATOR',now(),now() from work_test_ids;
insert into auth.sessions(id,user_id,factor_id,aal,created_at,updated_at) select session_id,owner_id,factor_id,'aal2'::auth.aal_level,now(),now() from work_test_ids union all select editor_session,editor_id,editor_factor,'aal2'::auth.aal_level,now(),now() from work_test_ids;
insert into public.work_members(email,user_id,role) select 'owner-fixture@example.invalid',owner_id,'owner' from work_test_ids union all select 'editor-fixture@example.invalid',editor_id,'editor' from work_test_ids;
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal1','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;
do $$begin
 if public.work_has_access('finance') then raise exception 'AAL1 was allowed'; end if;
 if (select count(*) from public.work_documents)<>0 then raise exception 'AAL1 financial data leak'; end if;
 if (select count(*) from public.work_settings)<>0 then raise exception 'AAL1 settings leak'; end if;
end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal2','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;
do $$
declare c jsonb;r jsonb;doc jsonb;line jsonb;cid uuid;supplier uuid;item uuid;ord uuid;inv uuid;purchase uuid;delivery uuid;payment uuid;allocation uuid;project uuid;expense uuid;evidence uuid=gen_random_uuid();accepted uuid=gen_random_uuid();order_line uuid;invoice_line uuid;purchase_line uuid;delivery_line uuid;reservation uuid;refused boolean;ids uuid[]='{}';rowid uuid;
begin
 c=public.work_business(jsonb_build_object('command','save','entity','customers','version',0,'data',jsonb_build_object('name','OPERATIONS FIXTURE','email','ops@example.invalid','phone','','address','Test address','assigned_to',auth.uid())));cid=(c->>'id')::uuid;
 c=public.work_business('{"command":"save","entity":"suppliers","version":0,"data":{"name":"FIXTURE SUPPLIER"}}');supplier=(c->>'id')::uuid;
 c=public.work_business('{"command":"save","entity":"items","version":0,"data":{"sku":"OPS-FIXTURE","name":"Test equipment","kind":"stock","unit":"unit","unit_minor":10000,"currency":"NGN"}}');item=(c->>'id')::uuid;
 doc=jsonb_build_object('kind','order','customer_id',cid,'title','Fixture order','document_date','2026-10-23','currency','NGN','lines',jsonb_build_array(jsonb_build_object('item_id',item,'description','Fixture equipment','quantity',10,'unit_minor',10000)));
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',doc));ord=(c->>'id')::uuid;
 c=public.work_business(jsonb_build_object('command','commercial_issue','id',ord,'version',1,'reason','Fixture issue reason'));
 if c->>'number' not like 'LUT-ORD-%' or (c->>'total_minor')::bigint<>100000 then raise exception 'Order numbering/totals failed';end if;
 select id into order_line from public.work_commercial_lines where record_id=ord;
 doc=doc||jsonb_build_object('kind','invoice','source_id',ord,'due_date','2026-10-25','lines',jsonb_build_array(jsonb_build_object('item_id',item,'source_line_id',order_line,'description','Partial fixture invoice','quantity',6,'unit_minor',10000)));
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',doc));inv=(c->>'id')::uuid;
 c=public.work_business(jsonb_build_object('command','commercial_issue','id',inv,'version',1,'reason','Fixture invoice issue'));
 select id into invoice_line from public.work_commercial_lines where record_id=inv;
 doc=jsonb_set(doc,'{lines,0,quantity}','5');
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',doc));
 refused=false;begin perform public.work_business(jsonb_build_object('command','commercial_issue','id',c->>'id','version',1,'reason','Overbilling fixture'));exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Overbilling allowed';end if;
 perform public.work_business(jsonb_build_object('command','misc','action','file','id',evidence,'area','finance','name','Fixture evidence','path',auth.uid()::text||'/'||evidence||'.jpg','size',10,'sha256',repeat('a',64)));
 insert into storage.objects(bucket_id,name) values('work-evidence',auth.uid()::text||'/'||evidence||'.jpg');
 c=public.work_business(jsonb_build_object('command','payment','request_key',gen_random_uuid(),'data',jsonb_build_object('customer_id',cid,'amount_minor',60000,'currency','NGN','paid_on','2026-10-23','method','Fixture transfer','description','Fixture payment','evidence_id',evidence,'confirmed',true)));
 payment=(c->>'id')::uuid;if payment is null then raise exception 'Payment not registered';end if;
 c=public.work_business(jsonb_build_object('command','allocate','request_key',gen_random_uuid(),'payment_id',payment,'invoice_id',inv,'amount_minor',60000));allocation=(c->>'id')::uuid;
 refused=false;begin perform public.work_business(jsonb_build_object('command','allocate','request_key',gen_random_uuid(),'payment_id',payment,'invoice_id',inv,'amount_minor',1));exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Over-allocation allowed';end if;
 if (select outstanding_minor from public.work_invoice_balances where id=inv)<>0 then raise exception 'Invoice balance not settled';end if;
 perform public.work_business(jsonb_build_object('command','finance_action','action','reverse_allocation','id',allocation,'reason','Fixture allocation correction'));
 perform public.work_business(jsonb_build_object('command','finance_action','action','refund','request_key',gen_random_uuid(),'payment_id',payment,'amount_minor',10000,'evidence_id',evidence,'reason','Fixture refund evidence'));
 c=public.work_business(jsonb_build_object('command','allocate','request_key',gen_random_uuid(),'payment_id',payment,'invoice_id',inv,'amount_minor',50000));
 doc=doc||jsonb_build_object('kind','credit','source_id',inv,'lines',jsonb_build_array(jsonb_build_object('item_id',item,'source_line_id',invoice_line,'description','Fixture credit','quantity',1,'unit_minor',10000)));
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',doc));
 perform public.work_business(jsonb_build_object('command','commercial_issue','id',c->>'id','version',1,'reason','Approved fixture credit'));
 if (select outstanding_minor from public.work_invoice_balances where id=inv)<>0 then raise exception 'Credit balance incorrect';end if;
 doc=jsonb_build_object('kind','purchase','supplier_id',supplier,'title','Fixture purchase','document_date','2026-10-23','currency','NGN','lines',jsonb_build_array(jsonb_build_object('item_id',item,'description','Fixture procurement','quantity',10,'unit_minor',8000)));
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',doc));purchase=(c->>'id')::uuid;
 perform public.work_business(jsonb_build_object('command','commercial_issue','id',purchase,'version',1,'reason','Fixture purchase approval'));
 select id into purchase_line from public.work_commercial_lines where record_id=purchase;
 perform public.work_business(jsonb_build_object('command','stock','action','move','kind','receive','item_id',item,'location','Fixture warehouse','quantity',7,'source_line_id',purchase_line,'reason','Fixture partial receiving','request_key',gen_random_uuid()));
 c=public.work_business(jsonb_build_object('command','stock','action','reserve','item_id',item,'location','Fixture warehouse','quantity',6,'order_id',ord,'request_key',gen_random_uuid()));reservation=(c->>'id')::uuid;
 refused=false;begin perform public.work_business(jsonb_build_object('command','stock','action','reserve','item_id',item,'location','Fixture warehouse','quantity',2,'order_id',ord,'request_key',gen_random_uuid()));exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Over-reservation allowed';end if;
 doc=jsonb_build_object('kind','delivery','customer_id',cid,'source_id',ord,'title','Fixture delivery','document_date','2026-10-23','currency','NGN','lines',jsonb_build_array(jsonb_build_object('item_id',item,'source_line_id',order_line,'description','Fixture dispatch','quantity',6,'unit_minor',10000)));
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',doc));delivery=(c->>'id')::uuid;
 perform public.work_business(jsonb_build_object('command','commercial_issue','id',delivery,'version',1,'reason','Fixture delivery issue'));
 select id into delivery_line from public.work_commercial_lines where record_id=delivery;
 perform public.work_business(jsonb_build_object('command','stock','action','move','kind','dispatch','item_id',item,'location','Fixture warehouse','quantity',6,'source_line_id',delivery_line,'reservation_id',reservation,'reason','Fixture dispatched equipment','request_key',gen_random_uuid()));
 if (select on_hand-reserved from public.work_stock_balances where item_id=item)<>1 then raise exception 'Stock ledger did not reconcile';end if;
 c=public.work_business(jsonb_build_object('command','save','entity','cases','version',0,'data',jsonb_build_object('kind','project','customer_id',cid,'title','Fixture software delivery','assigned_to',auth.uid())));project=(c->>'id')::uuid;
 c=public.work_business(jsonb_build_object('command','save','entity','tasks','version',0,'data',jsonb_build_object('case_id',project,'title','Fixture acceptance milestone','assigned_to',auth.uid(),'billable',true)));
 refused=false;begin perform public.work_business(jsonb_build_object('command','save','entity','cases','id',project,'version',1,'data',jsonb_build_object('kind','project','customer_id',cid,'title','Fixture software delivery','status','completed','priority','normal','accepted_by','Fixture customer','assigned_to',auth.uid())));exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Project completed without acceptance evidence';end if;
 perform public.work_business(jsonb_build_object('command','misc','action','file','id',accepted,'area','projects','name','Fixture acceptance','path',auth.uid()::text||'/'||accepted||'.jpg','size',10,'sha256',repeat('b',64)));
 insert into storage.objects(bucket_id,name) values('work-evidence',auth.uid()::text||'/'||accepted||'.jpg');
 perform public.work_business(jsonb_build_object('command','save','entity','cases','id',project,'version',1,'data',jsonb_build_object('kind','project','customer_id',cid,'title','Fixture software delivery','status','completed','priority','normal','accepted_by','Fixture customer','acceptance_id',accepted,'assigned_to',auth.uid())));
 c=public.work_business(jsonb_build_object('command','expense','action','save','data',jsonb_build_object('supplier_id',supplier,'title','Fixture shipping bill','category','shipping','amount_minor',10000,'currency','NGN','incurred_on','2026-10-23','evidence_id',evidence)));expense=(c->>'id')::uuid;
 perform public.work_business(jsonb_build_object('command','expense','action','submit','id',expense,'version',1));
 perform public.work_business(jsonb_build_object('command','expense','action','approve','id',expense,'version',2,'reason','Owner fixture exception'));
 perform public.work_business(jsonb_build_object('command','expense','action','pay','expense_id',expense,'amount_minor',10000,'paid_on','2026-10-23','evidence_id',evidence,'request_key',gen_random_uuid()));
 refused=false;begin perform public.work_business(jsonb_build_object('command','expense','action','pay','expense_id',expense,'amount_minor',1,'paid_on','2026-10-23','evidence_id',evidence,'request_key',gen_random_uuid()));exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Supplier overpayment allowed';end if;
 c=public.work_business(jsonb_build_object('command','bank','action','import','rows',jsonb_build_array(jsonb_build_object('posted_on','2026-10-23','amount_minor',60000,'currency','NGN','reference','FIXTURE BANK'))));
 if (c->>'inserted')::int<>1 then raise exception 'Bank import failed';end if;
 c=public.work_business(jsonb_build_object('command','bank','action','import','rows',jsonb_build_array(jsonb_build_object('posted_on','2026-10-23','amount_minor',60000,'currency','NGN','reference','FIXTURE BANK'))));
 if (c->>'inserted')::int<>0 then raise exception 'Duplicate bank import allowed';end if;
 perform public.work_business(jsonb_build_object('command','bank','action','match','id',(select id from public.work_bank_lines where reference='FIXTURE BANK'),'payment_id',payment));
 if not (select reconciled from public.work_payments where id=payment) then raise exception 'Bank reconciliation failed';end if;
 c=public.work_customer_statement(cid,null,null,'NGN');
 if jsonb_array_length(c->'events')<>4 then raise exception 'Statement duplicates or omits events';end if;
end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',editor_id,'aal','aal2','session_id',editor_session)::text,true) from work_test_ids;
set local role authenticated;
do $$declare refused boolean;begin
 if (select count(*) from public.work_customers)<>0 or (select count(*) from public.work_commercial)<>0 or (select count(*) from public.work_files)<>0 then raise exception 'Editor business data leak';end if;
 refused=false;begin perform public.work_business('{"command":"save","entity":"customers","version":0,"data":{"name":"Unauthorized"}}');exception when insufficient_privilege then refused=true;end;if not refused then raise exception 'Editor could create customer';end if;
 refused=false;begin update public.work_payments set amount_minor=1;exception when insufficient_privilege then refused=true;end;if not refused then raise exception 'Direct payment update allowed';end if;
end;$$;
reset role;
insert into private.work_job_config(id,proof_hash) values(1,encode(sha256(convert_to(repeat('b',64),'UTF8')),'hex')) on conflict(id) do update set proof_hash=excluded.proof_hash;
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal2','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;
do $$declare c jsonb;cid uuid;quote uuid;share uuid;refused boolean;doc jsonb;order_data jsonb;
begin
 select id into cid from public.work_customers where name='OPERATIONS FIXTURE';
 c=public.work_business(jsonb_build_object('command','quote_create','customer_id',cid));quote=(c->>'document_id')::uuid;
 perform public.work_business(jsonb_build_object('command','quote_mutate','id',quote,'version',1,'action','issue'));
 perform public.work_business(jsonb_build_object('command','portal_admin','action','member','customer_id',cid,'email','portal-fixture@example.invalid','active',true));
 perform public.work_business(jsonb_build_object('command','portal_admin','action','share','customer_id',cid,'document_id',quote,'active',true));
 select id into share from public.work_portal_shares where document_id=quote;
 perform public.work_customer_portal(repeat('b',64),jsonb_build_object('action','request','email','portal-fixture@example.invalid','token_hash',repeat('a',64),'cipher','TEST-ONLY-NOT-A-REAL-EMAIL'));
 perform public.work_customer_portal(repeat('b',64),jsonb_build_object('action','exchange','token_hash',repeat('a',64),'session_hash',repeat('c',64)));
 refused=false;begin perform public.work_customer_portal(repeat('b',64),jsonb_build_object('action','exchange','token_hash',repeat('a',64),'session_hash',repeat('d',64)));exception when raise_exception then refused=true;end;if not refused then raise exception 'Portal token replay accepted';end if;
 c=public.work_customer_portal(repeat('b',64),jsonb_build_object('action','state','session_hash',repeat('c',64)));
 if jsonb_array_length(c->'documents')<>1 or jsonb_array_length(c->'customers')<>1 then raise exception 'Portal organization boundary failed';end if;
 c=public.work_customer_portal(repeat('b',64),jsonb_build_object('action','document','share_id',share,'session_hash',repeat('c',64)));
 if c->'legacy'->>'number' is null then raise exception 'Shared quotation missing';end if;
 perform public.work_customer_portal(repeat('b',64),jsonb_build_object('action','accept','share_id',share,'session_hash',repeat('c',64)));
 if not exists(select 1 from public.work_quotes where document_id=quote and outcome='accepted' and accepted_by='portal-fixture@example.invalid') then raise exception 'Portal acceptance not recorded';end if;
 select payload into doc from public.work_documents where id=quote;
 order_data=jsonb_build_object('kind','order','customer_id',cid,'quote_id',quote,'title','Accepted quote order fixture','document_date','2026-10-23','currency',doc->>'currency','discount_minor',doc->'discount_minor','tax_bps',doc->'tax_bps','lines',doc->'items');
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',order_data));
 perform public.work_business(jsonb_build_object('command','commercial_issue','id',c->>'id','version',1,'reason','First accepted quote conversion'));
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',order_data));
 refused=false;begin perform public.work_business(jsonb_build_object('command','commercial_issue','id',c->>'id','version',1,'reason','Duplicate accepted quote conversion'));exception when raise_exception then refused=true;end;
 if not refused or (select count(*) from public.work_commercial where quote_id=quote and status='issued')<>1 then raise exception 'Accepted quotation issued as multiple orders';end if;

 refused=false;begin perform public.work_customer_portal(repeat('b',64),jsonb_build_object('action','document','share_id',gen_random_uuid(),'session_hash',repeat('c',64)));exception when insufficient_privilege then refused=true;end;if not refused then raise exception 'Portal arbitrary share access';end if;
 perform public.work_business(jsonb_build_object('command','portal_admin','action','member','customer_id',cid,'email','portal-fixture@example.invalid','active',false));
 c=public.work_customer_portal(repeat('b',64),jsonb_build_object('action','state','session_hash',repeat('c',64)));
 if jsonb_array_length(c->'documents')<>0 then raise exception 'Revoked customer retained access';end if;
 refused=false;begin perform public.work_customer_portal(repeat('e',64),'{}');exception when insufficient_privilege then refused=true;end;if not refused then raise exception 'Forged portal proof accepted';end if;
 c=public.work_business_job(repeat('b',64),jsonb_build_object('action','ingest','request_key','5f0fb561-9f26-4a9f-a531-31c62defce23','name','ENQUIRY FIXTURE','email','enquiry-fixture@example.invalid','subject','Fixture enquiry','message','TEST ONLY enquiry fixture','source','website-contact'));
 if c->>'reference' is null then raise exception 'Durable enquiry ingestion failed';end if;
 c=public.work_business_job(repeat('b',64),jsonb_build_object('action','ingest','request_key','5f0fb561-9f26-4a9f-a531-31c62defce23','name','ENQUIRY FIXTURE','email','enquiry-fixture@example.invalid','subject','Fixture enquiry','message','TEST ONLY enquiry fixture','source','website-contact'));
 if (select count(*) from public.work_enquiries where name='ENQUIRY FIXTURE')<>1 then raise exception 'Enquiry retry duplicated';end if;
 perform public.work_business(jsonb_build_object('command','misc','action','grant','email','editor-fixture@example.invalid','area','sales','scope','assigned','write_access',true,'approve_access',false));
end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',editor_id,'aal','aal2','session_id',editor_session)::text,true) from work_test_ids;
set local role authenticated;
do $$declare c jsonb;cid uuid;qid uuid;refused boolean;begin
 c=public.work_business('{"command":"save","entity":"customers","version":0,"data":{"name":"ASSIGNED SALES FIXTURE"}}');cid=(c->>'id')::uuid;
 c=public.work_business(jsonb_build_object('command','quote_create','customer_id',cid));qid=(c->>'document_id')::uuid;
 perform public.work_business(jsonb_build_object('command','quote_mutate','id',qid,'version',1,'action','issue'));
 if not exists(select 1 from public.work_documents where id=qid and status='issued') then raise exception 'Assigned sales quotation access failed';end if;
 if exists(select 1 from public.work_documents where kind='receipt') then raise exception 'Sales grant leaked receipts';end if;
 if exists(select 1 from public.work_customers where name='OPERATIONS FIXTURE') then raise exception 'Assignment scope bypass';end if;
 refused=false;begin perform public.work_business('{"command":"payment","request_key":"ba41a718-06b0-4418-8812-badff93c4110","data":{}}');exception when insufficient_privilege then refused=true;end;if not refused then raise exception 'Sales operator could record payments';end if;
end;$$;

reset role;
set local role anon;
do $$declare refused boolean;begin
 refused=false;begin perform public.work_business('{"command":"payment"}');exception when insufficient_privilege then refused=true;end;if not refused then raise exception 'Anonymous business RPC allowed';end if;
end;$$;
reset role;


select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal2','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;
do $$declare c jsonb;cid uuid;k uuid;change_id uuid;refused boolean;n integer;
begin
 select id into cid from public.work_customers where name='OPERATIONS FIXTURE';
 c=public.work_business(jsonb_build_object('command','save','entity','cases','version',0,'data',jsonb_build_object('kind','project','customer_id',cid,'title','LAB ACCEPTANCE FIXTURE','category','installation-labs','assigned_to',auth.uid())));k=(c->>'id')::uuid;
 c=public.work_business(jsonb_build_object('command','delivery_work','action','template','case_id',k,'request_key',gen_random_uuid()));
 if (c->>'created')::integer<>6 or (select count(*) from public.work_tasks where case_id=k)<>6 then raise exception 'Lab checklist did not create exactly six tasks';end if;
 refused=false;begin perform public.work_business(jsonb_build_object('command','delivery_work','action','template','case_id',k,'request_key',gen_random_uuid()));exception when raise_exception then refused=true;end;if not refused then raise exception 'Duplicate service checklist created';end if;
 refused=false;begin perform public.work_business(jsonb_build_object('command','save','entity','cases','id',k,'version',1,'data',jsonb_build_object('kind','project','customer_id',cid,'title','LAB ACCEPTANCE FIXTURE','status','waiting','priority','normal','assigned_to',auth.uid())));exception when raise_exception then refused=true;end;if not refused then raise exception 'Work paused without a reason';end if;
 perform public.work_business(jsonb_build_object('command','delivery_work','action','service','case_id',k,'version',0,'data',jsonb_build_object('coverage','Fixture service only','pause_reason','Waiting for fixture access','agreed_response_minutes','60')));
 if not exists(select 1 from public.work_cases where id=k and response_due_at is not null) then raise exception 'Agreed business response target was not calculated';end if;
 perform public.work_business(jsonb_build_object('command','save','entity','cases','id',k,'version',2,'data',jsonb_build_object('kind','project','customer_id',cid,'title','LAB ACCEPTANCE FIXTURE','status','waiting','priority','normal','assigned_to',auth.uid())));
 if not exists(select 1 from public.work_case_events where case_id=k and previous_status='open' and status='waiting') then raise exception 'Status history missing';end if;
 c=public.work_business(jsonb_build_object('command','delivery_work','action','change','case_id',k,'request_key',gen_random_uuid(),'data',jsonb_build_object('summary','Fixture scope change','details','Add one approved installation visit','amount_minor',0,'currency','NGN')));change_id=(c->>'id')::uuid;
 perform public.work_business(jsonb_build_object('command','delivery_work','action','decide','case_id',k,'id',change_id,'version',1,'decision','approved','reason','Explicit owner fixture exception'));
 refused=false;begin perform public.work_business(jsonb_build_object('command','delivery_work','action','decide','case_id',k,'id',change_id,'version',2,'decision','applied','reason','Missing downstream billing link'));exception when raise_exception then refused=true;end;if not refused then raise exception 'Change applied without revised order or milestone';end if;

end;$$;
reset role;
do $$begin if private.work_working_deadline('2026-10-23 15:30:00+00',60)<>'2026-10-26 08:30:00+00'::timestamptz then raise exception 'Business deadline failed Friday/weekend boundary';end if;end;$$;
-- Scoped worker backup, recovery manifest and receipt states. No real files or
-- Google operations are performed in this rollback-only database fixture.
set local role anon;
do $$declare b jsonb;pending jsonb;denied boolean;begin
 denied=false;begin perform public.work_backup_job(repeat('e',64),'{"action":"begin"}');exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Forged backup proof accepted';end if;
 b=public.work_backup_job(repeat('b',64),'{"action":"begin"}');
 if b->'snapshot'->'private.work_counters' is null or b->'snapshot'->'work_payments' is null or b->'snapshot'->'auth_users_included'<>'false'::jsonb or jsonb_array_length(b->'files')<2 then raise exception 'Backup recovery coverage incomplete';end if;
 perform set_config('request.headers',jsonb_build_object('x-lutera-backup-proof',repeat('b',64))::text,true);
 insert into storage.objects(bucket_id,name) values('work-backups',b->>'path');
 denied=false;begin insert into storage.objects(bucket_id,name) values('work-backups','unauthorized-object');exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Unregistered backup object accepted';end if;
 perform public.work_backup_job(repeat('b',64),jsonb_build_object('action','primary','id',b->>'id','sha256',repeat('a',64),'bytes',123,'file_count',2));
 pending=public.work_backup_job(repeat('b',64),'{"action":"pending"}');if jsonb_array_length(pending)<>1 then raise exception 'Primary copy not retained for offsite retry';end if;
 denied=false;begin perform public.work_backup_job(repeat('b',64),jsonb_build_object('action','offsite','id',b->>'id','sha256',repeat('e',64),'drive_id','fixture-drive-file'));exception when raise_exception then denied=true;end;if not denied then raise exception 'Offsite digest mismatch accepted';end if;
 perform public.work_backup_job(repeat('b',64),jsonb_build_object('action','offsite','id',b->>'id','sha256',repeat('a',64),'drive_id','fixture-drive-file'));
 if public.work_backup_job(repeat('b',64),'{"action":"begin"}') is not null then raise exception 'Duplicate daily backup created';end if;
 perform set_config('request.headers','{}',true);
 if exists(select 1 from storage.objects where bucket_id='work-backups') then raise exception 'Anonymous encrypted backup exposed';end if;
 denied=false;begin perform 1 from public.work_backup_runs;exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Anonymous backup metadata exposed';end if;
end;$$;
reset role;
select 'PASS: CRM, orders, staged invoices, evidence receipts, allocations, refund/credit reconciliation, procurement, stock reservations/dispatch, project acceptance, expenses and bank matching; denied editor/anonymous access. All fixtures rolled back.' result;
rollback;
